            fmt.Printf("  FAIL: length mismatch\n")
        } else {
            for i, v := range result {
                if v != tt.expected[i] {
                    fmt.Printf("  FAIL: value mismatch at index %d\n", i)
                    break
                }
            }
        }
    }
}
